/* Version 2 optional preferences; no background writes or automatic merging. */
(function(root){'use strict';
const PREFS=['nando-recordatorios-v1','deudas-lang-v1','deudas-currency-pref-v1','nando-deudas-sort-v1','deudas-budget-v1'];const SNAP='nando-prefs-recovery-v1:';const JOURNAL='nando-restore-journal-v1';
const enums={'deudas-lang-v1':['es','en'],'deudas-currency-pref-v1':['USD','COP','EUR'],'nando-deudas-sort-v1':['balance-asc','balance-desc','rate-asc','rate-desc']};
// 1.8 Gastos fijos: two optional parts of a version 2 backup (gastosFijos, gastosCategorias).
// Old backups without them restore fine and leave the expenses of this device untouched.
const GKEY='mpdd-gastos-fijos-v1',GCATS='mpdd-gastos-categorias-v1',GKEYS=[GKEY,GCATS];
function readGastos(store){const C=root.MPDDGastosCore;if(!C)return {};const out={};try{const v=store.getItem(GKEY);if(v!==null)out.gastosFijos=C.sanitize(JSON.parse(v))}catch(_){}try{const v=store.getItem(GCATS);if(v!==null)out.gastosCategorias=cleanCats(JSON.parse(v))}catch(_){}return out}
function cleanCats(v){const icons=(root.MPDDGastosCore&&root.MPDDGastosCore.CUSTOM_ICONS)||[];return (Array.isArray(v)?v:[]).filter(c=>c&&typeof c.key==='string'&&/^c-[a-z0-9-]{1,36}$/.test(c.key)&&typeof c.label==='string'&&c.label.trim()&&c.label.length<=30).slice(-40).map(c=>({key:c.key,label:c.label.trim(),icon:icons.includes(c.icon)?c.icon:'⭐'}))}
function validateGastos(data){const out={gastos:null,gastosCategorias:null};const C=root.MPDDGastosCore;if(data.gastosFijos!==undefined){if(!Array.isArray(data.gastosFijos)||data.gastosFijos.length>2000||!C)throw Error('Los gastos fijos del respaldo no son válidos.');root.DebtBackup.validateBackup(JSON.stringify({version:1,debts:[],gastos:data.gastosFijos}));out.gastos=C.sanitize(data.gastosFijos)}if(data.gastosCategorias!==undefined){if(!Array.isArray(data.gastosCategorias)||data.gastosCategorias.length>200)throw Error('Las categorías de gastos fijos del respaldo no son válidas.');root.DebtBackup.validateBackup(JSON.stringify({version:1,debts:[],cats:data.gastosCategorias}));out.gastosCategorias=cleanCats(data.gastosCategorias)}return out}
// fin 1.8
function validatePref(k,v){if(typeof v!=='string'||v.length>1000000)throw Error('Preferencia inválida o demasiado grande.');if(enums[k]&&!enums[k].includes(v))throw Error('Preferencia no admitida: '+k);if(k==='deudas-budget-v1'){let x;try{x=JSON.parse(v)}catch(_){throw Error('Presupuesto inválido.')}const fields=['income','essential','fixed','variable','minimums','extra'];if(!x||typeof x!=='object'||Array.isArray(x)||Object.keys(x).some(k=>!fields.includes(k))||fields.some(k=>typeof x[k]!=='number'||!Number.isFinite(x[k])||x[k]<0||x[k]>1e10))throw Error('Presupuesto inválido.');}if(k==='nando-recordatorios-v1'){let x;try{x=JSON.parse(v)}catch(_){throw Error('Recordatorios inválidos.')}if(!x||typeof x!=='object'||Array.isArray(x))throw Error('Recordatorios inválidos.'); // Reuse full tree inspection including dangerous keys.
root.DebtBackup.validateBackup(JSON.stringify({version:1,debts:[],prefs:x}));for(const p of Object.values(x)){if(!p||typeof p!=='object'||Array.isArray(p))throw Error('Recordatorio inválido.');for(const d of ['cutoffDay','paymentDay'])if(p[d]!=null&&(!Number.isInteger(p[d])||p[d]<1||p[d]>31))throw Error('Día de recordatorio inválido.');if(p.beforeDays!=null&&(!Number.isInteger(p.beforeDays)||p.beforeDays<0||p.beforeDays>90))throw Error('Anticipación inválida.');for(const f of ['cutoffEnabled','paymentEnabled','sameDay'])if(p[f]!=null&&typeof p[f]!=='boolean')throw Error('Opción de recordatorio inválida.');if(p.paidThrough!=null&&typeof p.paidThrough!=='string')throw Error('Fecha de recordatorio inválida.')}}return v}
function readPrefs(store){let out=Object.create(null);for(const k of PREFS){const v=store.getItem(k);if(v!==null)out[k]=validatePref(k,v)}return out}
function validate(raw){if(typeof raw!=='string'||new TextEncoder().encode(raw).length>root.DebtBackup.MAX_BACKUP_BYTES)throw Error('Archivo inválido o demasiado grande.');let data;try{data=JSON.parse(raw)}catch(_){throw Error('El archivo no contiene JSON válido.')}if(data?.version===1){let v=root.DebtBackup.validateBackup(raw);return {...v,version:1,preferences:null}}if(data?.version!==2||!data.preferences||typeof data.preferences!=='object'||Array.isArray(data.preferences))throw Error('Formato de respaldo no compatible.');let v=root.DebtBackup.validateBackup(JSON.stringify({version:1,debts:data.debts,preferences:data.preferences}));let prefs=Object.create(null);for(const [k,x] of Object.entries(data.preferences)){if(!PREFS.includes(k))throw Error('El respaldo contiene una preferencia no admitida.');prefs[k]=validatePref(k,x)}return {...v,version:2,raw,preferences:prefs,...validateGastos(data)}}
function create(store,debts){const preferences=readPrefs(store),raw=JSON.stringify(Object.assign({version:2,debts,preferences},readGastos(store)),null,2);validate(raw);return raw}
function snapshotState(store){let out=Object.create(null);out[root.DebtStorage.KEY]=store.getItem(root.DebtStorage.KEY);for(const k of PREFS)out[k]=store.getItem(k);for(const k of GKEYS)out[k]=store.getItem(k);return out}
function sameState(store,prior){return Object.keys(prior).every(k=>store.getItem(k)===prior[k])}
function restore(store,raw,expected,restorePrefs,id){if(store.getItem(JOURNAL)!==null)throw Error('Hay una restauración interrumpida que requiere revisión. No se modificó nada.');const incoming=validate(raw),now=root.DebtStorage.read(store);if(!now.ok||!sameState(store,expected))throw Error('Los datos cambiaron o requieren revisión; no se restauró nada.');const targets=Object.create(null);targets[root.DebtStorage.KEY]=JSON.stringify(incoming.debts);if(restorePrefs&&incoming.preferences)for(const [k,v] of Object.entries(incoming.preferences))targets[k]=v;/* 1.8: restored expenses count as edited now, so the sync keeps them. */if(incoming.gastos){const now=new Date().toISOString();targets[GKEY]=JSON.stringify(incoming.gastos.map(g=>g.deleted?g:Object.assign({},g,{updatedAt:now})))}if(incoming.gastosCategorias)targets[GCATS]=JSON.stringify(incoming.gastosCategorias);const prior=Object.create(null);for(const k of Object.keys(targets))prior[k]=store.getItem(k);let sk=null;for(let n=0;n<8;n++){let key=SNAP+id();if(store.getItem(key)===null){sk=key;break}}if(!sk)throw Error('No se pudo crear una copia única de seguridad.');const snapshot=JSON.stringify({version:1,values:prior});try{store.setItem(sk,snapshot);if(store.getItem(sk)!==snapshot)throw Error()}catch(_){throw Error('No se pudo guardar la copia anterior. No se restauró nada.')}
const journal=JSON.stringify({version:1,snapshot:sk,prior,targets});try{store.setItem(JOURNAL,journal);if(store.getItem(JOURNAL)!==journal)throw Error();}catch(_){throw Error('No se pudo preparar el registro de recuperación. No se restauró nada.')}try{for(const [k,v] of Object.entries(targets)){store.setItem(k,v);if(store.getItem(k)!==v)throw Error('Falló la verificación.')}store.removeItem(JOURNAL);if(store.getItem(JOURNAL)!==null)throw Error('No se pudo verificar el cierre de la restauración.')}catch(e){let rollback=true;for(const [k,v] of Object.entries(prior))try{if(v===null)store.removeItem(k);else store.setItem(k,v);if(store.getItem(k)!==v)rollback=false}catch(_){rollback=false}if(rollback)try{store.removeItem(JOURNAL)}catch(_){}throw Error(rollback?'No se completó la restauración; los datos anteriores fueron restituidos.':'No se pudo verificar la restitución. Conserva el dispositivo y la copia local de seguridad para recuperación.')}
if(GKEYS.some(k=>Object.hasOwn(targets,k)))try{root.document&&root.document.dispatchEvent(new root.CustomEvent('mpdd:gastoschange',{detail:{source:'restore'}}))}catch(_){}return {debts:incoming.debts,count:incoming.count,preferencesRestored:!!(restorePrefs&&incoming.preferences),gastosRestored:!!incoming.gastos,snapshot:sk};}
function inspectRecovery(store){const raw=store.getItem(JOURNAL);if(raw===null)return {pending:false};let j;try{j=JSON.parse(raw);if(!j||j.version!==1||typeof j.snapshot!=='string'||!j.snapshot.startsWith(SNAP)||!j.prior||!j.targets||typeof j.prior!=='object'||typeof j.targets!=='object'||Array.isArray(j.prior)||Array.isArray(j.targets))throw Error();const names=Object.keys(j.prior),targetNames=Object.keys(j.targets),allowed=[root.DebtStorage.KEY,...PREFS,...GKEYS];if(!names.length||names.length!==targetNames.length||names.some(k=>!allowed.includes(k)||!Object.hasOwn(j.targets,k)||(j.prior[k]!==null&&typeof j.prior[k]!=='string')||typeof j.targets[k]!=='string'))throw Error();const snapshot=store.getItem(j.snapshot);if(!snapshot)throw Error();const parsed=JSON.parse(snapshot);if(parsed.version!==1||JSON.stringify(parsed.values)!==JSON.stringify(j.prior))throw Error();return {pending:true,valid:true,keys:names,conflict:names.some(k=>{const v=store.getItem(k);return v!==j.prior[k]&&v!==j.targets[k]})};}catch(_){return {pending:true,valid:false,conflict:true,keys:[]}}}
function recoverPrior(store,confirmed,id){if(confirmed!==true)throw Error('Se necesita confirmación para recuperar la copia anterior.');const state=inspectRecovery(store);if(!state.pending||!state.valid||state.conflict)throw Error('El registro de recuperación requiere revisión manual. No se modificó nada.');const raw=store.getItem(JOURNAL),j=JSON.parse(raw),observed=Object.create(null);for(const k of state.keys)observed[k]=store.getItem(k);let copy=null;for(let i=0;i<8;i++){const candidate=SNAP+id();if(store.getItem(candidate)===null){copy=candidate;break}}if(!copy)throw Error('No se pudo guardar una copia única.');const snapshot=JSON.stringify({version:1,values:observed});try{store.setItem(copy,snapshot);if(store.getItem(copy)!==snapshot)throw Error();if(store.getItem(JOURNAL)!==raw||!sameState(store,observed))throw Error();}catch(_){throw Error('No se pudo proteger el estado actual. No se modificó.')}try{for(const [k,v] of Object.entries(j.prior)){if(v===null)store.removeItem(k);else store.setItem(k,v);if(store.getItem(k)!==v)throw Error()}store.removeItem(JOURNAL);if(store.getItem(JOURNAL)!==null)throw Error()}catch(_){throw Error('La recuperación quedó incompleta. El registro y las copias se conservaron para revisión.')}return {snapshot:copy,keys:state.keys};}

root.DebtBackupPlus={PREFS,validate,create,snapshotState,sameState,restore,readPrefs,JOURNAL,inspectRecovery,recoverPrior};
})(globalThis);
